package com.ebdf.controller;
import com.ebdf.dao.PortalDAO; import com.google.gson.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.*;
@WebServlet("/api/notifications") public class NotificationsServlet extends HttpServlet {
 private final PortalDAO dao=new PortalDAO(); private final Gson gson=new Gson();
 private Integer user(HttpServletRequest q,HttpServletResponse p)throws IOException{HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){p.setStatus(401);p.getWriter().write("{\"message\":\"Please login first\"}");return null;}return ((Number)s.getAttribute("userId")).intValue();}
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException{p.setContentType("application/json");p.setCharacterEncoding("UTF-8");Integer id=user(q,p);if(id==null)return;try{p.getWriter().write(gson.toJson(dao.notifications(id)));}catch(Exception e){getServletContext().log("notifications failed",e);p.setStatus(500);p.getWriter().write("{\"message\":\"Unable to load notifications\"}");}}
 protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{p.setContentType("application/json");p.setCharacterEncoding("UTF-8");Integer uid=user(q,p);if(uid==null)return;try{JsonObject j=gson.fromJson(q.getReader(),JsonObject.class);String action=j.get("action").getAsString();boolean ok=false;if("read".equals(action))ok=dao.markNotificationRead(j.get("notificationId").getAsInt(),uid);else if("delete".equals(action))ok=dao.deleteNotification(j.get("notificationId").getAsInt(),uid);else if("readAll".equals(action)){dao.markAllNotificationsRead(uid);ok=true;}else{p.setStatus(400);p.getWriter().write("{\"message\":\"Invalid action\"}");return;}if(!ok){p.setStatus(404);p.getWriter().write("{\"message\":\"Notification not found\"}");return;}p.getWriter().write("{\"message\":\"Notification updated\"}");}catch(Exception e){getServletContext().log("notification update failed",e);p.setStatus(400);p.getWriter().write("{\"message\":\"Unable to update notification\"}");}}
}
